 * BBCode-to-HTML converter.
 *
 * Architecture: a real tokenizer (text vs. open tag vs. close tag) feeding a
 * tag stack. No regex soup — the tokenizer scans linearly and the stack
 * handles nesting.
 *
 * Nesting / auto-close rule:
 *   A closing tag closes the *nearest* open element with a matching name.
 *   Any elements still on the stack above it are auto-closed (emitted) and
 *   NOT re-opened. So "[b][i]x[/b]" renders "<b><i>x</i></b>" — the `i`
 *   is auto-closed by the [/b] and nothing is re-opened afterwards.
 *
 * Fallback rules:
 *   - Unknown tag names (not in the supported set) render as literal text,
 *     including their brackets.
 *   - A closing tag with no matching open element renders as literal text.
 *   - Elements left unclosed at end of input are simply closed in reverse
 *     order (they render normally; only *mismatched* closers become text).
 *
 * Escaping:
 *   - All text content is HTML-escaped.
 *   - [code] bodies are escaped and never parsed for BBCode (no tokenizing
 *     inside code until the matching [/code] appears).
 *   - [url=target] targets go through a scheme allowlist (http, https, mailto,
 *     ftp, relative). Disallowed schemes (e.g. javascript:) make the whole
 *     tag render as plain literal text.
 */

export function bbcodeToHtml(input: string): string {
  return new Converter(input).run();
}

// ---------------------------------------------------------------------------
// Tokenizer
// ---------------------------------------------------------------------------

type Token =
  | { type: 'text'; value: string }
  | { type: 'open'; name: string; attr?: string }
  | { type: 'close'; name: string };

/** Tags we support. Anything else is literal text. */
const SUPPORTED = new Set(['b', 'i', 'u', 'url', 'quote', 'code', 'list', '*']);

const TAG_NAME = /^[a-zA-Z*]+/;

class Tokenizer {
  private pos = 0;

  constructor(private readonly src: string) {}

  tokenize(): Token[] {
    const tokens: Token[] = [];
    let text = '';

    const flush = () => {
      if (text) {
        tokens.push({ type: 'text', value: text });
        text = '';
      }
    };

    while (this.pos < this.src.length) {
      const ch = this.src[this.pos];
      if (ch === '[') {
        const tok = this.tryTag();
        if (tok) {
          flush();
          tokens.push(tok);
          continue;
        }
      }
      text += ch;
      this.pos++;
    }
    flush();
    return tokens;
  }

  /**
   * Attempt to read a tag at the current position ('['). Returns null (and
   * leaves position untouched) if it isn't a well-formed tag we recognize;
   * the caller then treats the '[' as ordinary text.
   */
  private tryTag(): Token | null {
    const src = this.src;
    if (src[this.pos + 1] === '/') {
      // Possible closing tag: [/name]
      const m = TAG_NAME.exec(src.slice(this.pos + 2));
      if (!m) return null;
      const name = m[0].toLowerCase();
      const end = this.pos + 2 + m[0].length;
      if (src[end] !== ']') return null;
      this.pos = end + 1;
      return { type: 'close', name };
    }

    // Possible opening tag: [name] or [name=attr]
    const m = TAG_NAME.exec(src.slice(this.pos + 1));
    if (!m) return null;
    const name = m[0].toLowerCase();
    let i = this.pos + 1 + m[0].length;

    let attr: string | undefined;
    if (src[i] === '=') {
      i++;
      const start = i;
      while (i < src.length && src[i] !== ']') i++;
      if (i >= src.length) return null; // no closing bracket -> literal
      attr = src.slice(start, i);
    }

    if (src[i] !== ']') return null;
    this.pos = i + 1;
    return { type: 'open', name, attr };
  }
}

// ---------------------------------------------------------------------------
// Renderer
// ---------------------------------------------------------------------------

/** Scheme allowlist for url targets (same treatment as any sanitizer). */
const URL_SCHEMES = new Set(['http', 'https', 'mailto', 'ftp']);

interface OpenElement {
  name: string;
  /** HTML emitted when this element is closed (closing tag + any wrapper). */
  closeHtml: string;
}

function escapeHtml(s: string): string {
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

/** True if the target is allowed under the scheme allowlist (or is relative). */
function isSafeUrl(target: string): boolean {
  const trimmed = target.trim();
  // Relative URLs (no scheme before the first ':') are fine.
  const schemeMatch = /^([a-zA-Z][a-zA-Z0-9+.-]*):/.exec(trimmed);
  if (!schemeMatch) return true;
  return URL_SCHEMES.has(schemeMatch[1].toLowerCase());
}

class Converter {
  private out = '';
  private stack: OpenElement[] = [];

  constructor(private readonly tokens: Token[]) {}

  run(): string {
    for (const tok of this.tokens) {
      switch (tok.type) {
        case 'text':
          this.out += escapeHtml(tok.value);
          break;
        case 'open':
          this.openTag(tok);
          break;
        case 'close':
          this.closeTag(tok.name);
          break;
      }
    }
    // Unclosed tags at EOF: close everything left, in reverse order.
    while (this.stack.length > 0) {
      this.out += this.stack.pop()!.closeHtml;
    }
    return this.out;
  }

  private openTag(tok: Extract<Token, { type: 'open' }>): void {
    const { name, attr } = tok;
    switch (name) {
      case 'b':
        this.out += '<b>';
        this.push(name, '</b>');
        break;
      case 'i':
        this.out += '<i>';
        this.push(name, '</i>');
        break;
      case 'u':
        this.out += '<u>';
        this.push(name, '</u>');
        break;

      case 'url': {
        const target = (attr ?? '').trim();
        if (!target || !isSafeUrl(target)) {
          // javascript: etc. -> whole tag becomes plain literal text.
          this.out += escapeHtml(`[url=${target}]`);
          this.push(name, ''); // marker so a later [/url] emits as text too
          break;
        }
        this.out += `<a href="${escapeHtml(target)}">`;
        this.push(name, '</a>');
        break;
      }

      case 'quote':
        if (attr) {
          this.out += `<blockquote><p class="quote-author">${escapeHtml(attr)}</p>`;
          this.push(name, '</blockquote>');
        } else {
          this.out += '<blockquote>';
          this.push(name, '</blockquote>');
        }
        break;

      case 'list':
        this.out += '<ul>';
        this.push(name, '</ul>');
        break;

      case '*': {
        // [*] items live directly inside [list]; split content on [*].
        const parent = topOf(this.stack);
        if (parent && parent.name === 'list') {
          this.out += '<li>';
          this.push('*', '</li>');
        } else {
          this.literalTag(`[*${attr ? '=' + attr : ''}]`, name);
        }
        break;
      }

      case 'code': {
        // Raw mode: consume verbatim until [/code], escaping everything and
        // ignoring inner BBCode entirely.
        const body = this.rawUntilClose('code');
        this.out += `<pre><code>${escapeHtml(body)}</code></pre>`;
        break;
      }

      default:
        // Unknown tag -> literal text.
        this.literalTag(`[${name}${attr ? '=' + attr : ''}]`, name);
        break;
    }
  }

  /**
   * Consume raw source until the matching [/name] close token appears
   * (nesting-aware for identical tags). The close tag itself is consumed.
   */
  private rawUntilClose(name: string): string {
    // We re-tokenize lazily from the remaining source: simplest correct way
    // to get verbatim text is scanning the original string. To do that we
    // reconstruct from the current token stream position instead: the
    // tokenizer already split things, so walk forward merging tokens back.
    let depth = 1;
    let raw = '';
    while (this.tokens.length > 0) {
      const t = this.tokens.shift()!;
      if (t.type === 'open' && t.name === name) {
        depth++;
        raw += `[${name}${t.attr ? '=' + t.attr : ''}]`;
      } else if (t.type === 'close' && t.name === name) {
        depth--;
        if (depth === 0) break;
        raw += `[/${name}]`;
      } else {
        raw += tokenToRaw(t);
      }
    }
    return raw;
  }

  private push(name: string, closeHtml: string): void {
    this.stack.push({ name, closeHtml });
  }

  /**
   * Handle a closing tag. Closes the nearest matching open element,
   * auto-closing anything above it on the stack (which is NOT re-opened).
   * If there's no matching open element, render the closer as literal text.
   */
  private closeTag(name: string): void {
    // Find nearest matching open element.
    let idx = -1;
    for (let i = this.stack.length - 1; i >= 0; i--) {
      if (this.stack[i].name === name) {
        idx = i;
        break;
      }
    }

    if (idx === -1) {
      // Unmatched closer: literal text fallback. But a bare [/url] that
      // pairs with an unsafe-url literal marker also lands here (marker was
      // pushed with name 'url'... handled above), so this is genuinely
      // unmatched tags like [/foo].
      this.out += escapeHtml(`[/${name}]`);
      return;
    }

    // Auto-close everything above it (no reopening).
    while (this.stack.length > idx + 1) {
      this.out += this.stack.pop()!.closeHtml;
    }
    this.out += this.stack.pop()!.closeHtml;
  }

  /** Emit an unknown/malformed tag as literal text and track it on the stack. */
  private literalTag(raw: string, name: string): void {
    this.out += escapeHtml(raw);
    // Track so that a matching closer is swallowed rather than leaked.
    this.push(name, '');
  }
}

