import { bbcodeToHtml } from '../src/index.js';

describe('nesting / auto-close', () => {
  it('properly nested tags close in order', () => {
    expect(bbcodeToHtml('[b][i]x[/i][/b]')).toBe('<b><i>x</i></b>');
  });

  it('[b][i]x[/b] auto-closes the i and reopens nothing', () => {
    expect(bbcodeToHtml('[b][i]x[/b]')).toBe('<b><i>x</i></b>');
  });

  it('auto-close does not reopen the inner tag afterwards', () => {
    expect(bbcodeToHtml('[b][i]x[/b]y')).toBe('<b><i>x</i></b>y');
  });

  it('multiple inner tags are all auto-closed by one closer', () => {
    expect(bbcodeToHtml('[b][i][u]x[/b]y')).toBe('<b><i><u>x</u></i></b>y');
  });

  it('unclosed tags at end of input are closed in reverse order', () => {
    expect(bbcodeToHtml('[b][i]x')).toBe('<b><i>x</i></b>');
  });
});

describe('[code] literalness', () => {
  it('inner bbcode is ignored and content is fully escaped', () => {
    expect(
      bbcodeToHtml('[code][b]not bold[/b] <script>alert(1)</script> & "quotes"[/code]')
    ).toBe(
      '<pre><code>[b]not bold[/b] &lt;script&gt;alert(1)&lt;/script&gt; &amp; &quot;quotes&quot;</code></pre>'
    );
  });

  it('unterminated [code] swallows the rest of the input verbatim', () => {
    expect(bbcodeToHtml('[code]x [b]bold')).toBe('<pre><code>x [b]bold</code></pre>');
  });
});

describe('url allowlist', () => {
  it('http and https targets become links', () => {
    expect(bbcodeToHtml('[url=https://example.com]hi[/url]')).toBe(
      '<a href="https://example.com">hi</a>'
    );
    expect(bbcodeToHtml('[url=http://example.com/a?b=1&c=2]q[/url]')).toBe(
      '<a href="http://example.com/a?b=1&amp;c=2">q</a>'
    );
  });

  it('javascript: renders as plain literal text', () => {
    expect(bbcodeToHtml('[url=javascript:alert(1)]click[/url]')).toBe(
      '[url=javascript:alert(1)]click'
    );
  });

  it('data: and vbscript: are also rejected as literals', () => {
    expect(bbcodeToHtml('[url=data:text/html,x]x[/url]')).toBe('[url=data:text/html,x]x');
    expect(bbcodeToHtml('[url=vbscript:msgbox(1)]x[/url]')).toBe('[url=vbscript:msgbox(1)]x');
  });

  it('the matching [/url] of a rejected url also becomes literal text', () => {
    expect(bbcodeToHtml('[url=javascript:x]t[/url] after')).toBe('[url=javascript:x]t after');
  });

  it('relative targets are allowed', () => {
    expect(bbcodeToHtml('[url=/page]home[/url]')).toBe('<a href="/page">home</a>');
  });

  it('mailto is allowed', () => {
    expect(bbcodeToHtml('[url=mailto:a@b.c]mail[/url]')).toBe(
      '<a href="mailto:a@b.c">mail</a>'
    );
  });

  it('scheme case is normalized (JaVaScRiPt: rejected)', () => {
    expect(bbcodeToHtml('[url=JaVaScRiPt:alert(1)]x[/url]')).toBe(
      '[url=JaVaScRiPt:alert(1)]x'
    );
  });
});

describe('[list] with [*] items', () => {
  it('splits items on [*]', () => {
    expect(bbcodeToHtml('[list][*]one[*]two[*]three[/list]')).toBe(
      '<ul><li>one</li><li>two</li><li>three</li></ul>'
    );
  });

  it('items can contain nested formatting', () => {
    expect(bbcodeToHtml('[list][*][b]bold[/b] item[/list]')).toBe(
      '<ul><li><b>bold</b> item</li></ul>'
    );
  });

  it('an unclosed list still closes its last item at EOF', () => {
    expect(bbcodeToHtml('[list][*]one[*]two')).toBe('<ul><li>one</li><li>two</li></ul>');
  });
});

describe('unknown and unclosed tag fallbacks', () => {
  it('unknown tags render as literal text', () => {
    expect(bbcodeToHtml('[spoiler]secret[/spoiler]')).toBe('[spoiler]secret[/spoiler]');
  });

  it('unknown tags with attributes render literally too', () => {
    expect(bbcodeToHtml('[foo=bar]x[/foo]')).toBe('[foo=bar]x[/foo]');
  });

  it('malformed brackets stay literal text', () => {
    expect(bbcodeToHtml('a [ not a tag ] b')).toBe('a [ not a tag ] b');
    expect(bbcodeToHtml('100% [and [unclosed')).toBe('100% [and [unclosed');
  });

  it('stray closers without an opener render as literal text', () => {
    expect(bbcodeToHtml('x[/b]y')).toBe('x[/b]y');
  });
});

describe('quote and general escaping', () => {
  it('[quote=author] renders a blockquote with author line', () => {
    expect(bbcodeToHtml('[quote=Alice]hi[/quote]')).toBe(
      '<blockquote><p class="quote-author">Alice</p>hi</blockquote>'
    );
  });

  it('all other text is HTML-escaped', () => {
    expect(bbcodeToHtml('<b>&"'</b>')).toBe('&lt;b&gt;&amp;&quot;&#39;&lt;/b&gt;');
  });
});
"})
